package com.alpharip.staffmod.BuildTimelapse.capture;
public final class CaptureSettings {private long interval=1000;private int width,height;private boolean hideHud=true,hideHand=true;public long getInterval(){return interval;}public void setInterval(long v){if(v<100)throw new IllegalArgumentException("min 100ms");interval=v;}public void setResolution(int w,int h){if(w<0||h<0||(w==0)!=(h==0))throw new IllegalArgumentException();width=w;height=h;}public int getWidth(){return width;}public int getHeight(){return height;}public boolean isHideHud(){return hideHud;}public void setHideHud(boolean v){hideHud=v;}public boolean isHideHand(){return hideHand;}public void setHideHand(boolean v){hideHand=v;}}
